pragma solidity ^0.8.20;

import {IERC721} from "@openzeppelin-contracts/interfaces/IERC721.sol";

enum Team {
    NO_TEAM,
    RED,
    BLUE,
    GREEN
}

/// This contract represents a game contract. GameToken can be used to interact with it.
/// There are functions that:
/// - do not require holding a GameToken to interact
/// - operate on all game tokens in the wallet
contract Game {
    // the game token
    address public gameToken;

    // maps a token to its current level
    mapping(uint256 tokenId => uint256 level) private _levelCounter;

    // maps a token to its retiree status
    mapping(uint256 tokenId => bool retired) private _retiredTokens;

    // maps an EOA or contract address to a team
    mapping(address holder => Team team) private _teamMembership;

    //////// Constructor ////////

    constructor(address _gameToken) {
        gameToken = _gameToken;
    }

    //////// Modifiers ////////

    modifier onlyTokenOwner(uint256 tokenId) {
        require(msg.sender == IERC721(gameToken).ownerOf(tokenId), "not owner");
        _;
    }

    modifier onlyActive(uint256 tokenId) {
        require(!_retiredTokens[tokenId], "token is retired");
        _;
    }

    //////// View methods ////////

    // determines the team of the token
    function teamOf(uint256 tokenId) public view returns (Team) {
        address holder = IERC721(gameToken).ownerOf(tokenId);

        return _teamMembership[holder];
    }

    function levelOf(uint256 tokenId) external view returns (uint256) {
        return _levelCounter[tokenId];
    }

    function isRetired(uint256 tokenId) external view returns (bool) {
        return _retiredTokens[tokenId];
    }

    //////// External methods ////////

    // increase the abilities of the token
    function train(uint256 tokenId) external onlyTokenOwner(tokenId) onlyActive(tokenId) {
        _levelCounter[tokenId]++;
    }

    // Prevents the token from competing in the game ever again.
    // This action cannot be undone.
    function retire(uint256 tokenId) external onlyTokenOwner(tokenId) {
        _retiredTokens[tokenId] = true;
    }

    // converts all tokens held by the sender to a different team
    function changeTeam(Team newTeam) external {
        require(newTeam != _teamMembership[msg.sender], "cant change to same team");
        _teamMembership[msg.sender] = newTeam;
    }
}
"},"src/examples/restricted-selector/RestrictedSelectorHook.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {IHook} from "@src/interfaces/IHook.sol";
import {Game} from "@src/examples/restricted-selector/Game.sol";

contract RestrictedSelectorHook is IHook {
    // privileged policy contracts
    address public createPolicy;
    address public stopPolicy;

    // target contract that will be active for this hook
    address public target;

    // token which, when held, restricts functionality of the wallet
    address public restrictedToken;

    // maps a token ID to an allowlisted function selector bitmap
    mapping(uint256 tokenId => uint256 bitmap) public functionSelectorBitmap;

    // tracks how many rentals a safe actively has
    mapping(address renter => uint256 count) public activeRentals;

    constructor(
        address _createPolicy,
        address _stopPolicy,
        address _target,
        address _restrictedToken
    ) {
        createPolicy = _createPolicy;
        stopPolicy = _stopPolicy;
        target = _target;
        restrictedToken = _restrictedToken;
    }

    modifier onlyCreatePolicy() {
        require(msg.sender == createPolicy, "not callable unless create policy");
        _;
    }

    modifier onlyStopPolicy() {
        require(msg.sender == stopPolicy, "not callable unless stop policy");
        _;
    }

    modifier onlySupportedTokens(address token) {
        require(token == restrictedToken, "token is not supported");
        _;
    }

    function _isFunctionSelectorAllowed(
        uint256 tokenId,
        uint256 selectorPosition
    ) internal view returns (bool) {
        // There are 256 bits in a uint256, so there can only be 256 positions for a function selector
        require(selectorPosition < 256, "bitmap index out of bounds");

        // shift a 1 to the bit that we're interested in
        uint256 mask = 1 << selectorPosition;

        // perform an AND operation on the mask and the bitmap. Check that it comes back as 0, meaning
        // it wasn't declared off-limits
        return (functionSelectorBitmap[tokenId] & mask) == 0;
    }

    // hook handler for when a rental has started
    function onStart(
        address safe,
        address token,
        uint256 identifier,
        uint256,
        bytes memory data
    ) external onlyCreatePolicy onlySupportedTokens(token) {
        // decode extra data as a bitmap
        uint256 bitmap = abi.decode(data, (uint256));

        // add bitmap entry for the token Id
        functionSelectorBitmap[identifier] = bitmap;

        // increment the total number of active rentals for the sender
        activeRentals[safe]++;
    }

    // hook handler for when a rental has stopped
    function onStop(
        address safe,
        address token,
        uint256 identifier,
        uint256,
        bytes memory
    ) external onlyStopPolicy onlySupportedTokens(token) {
        // remove token from mapping
        delete functionSelectorBitmap[identifier];

        // decrement the total number of active rentals for the sender
        activeRentals[safe]--;
    }

    // Triggers on each transaction from a rental safe
    function onTransaction(
        address safe,
        address to,
        uint256,
        bytes memory data
    ) external view {
        // make sure only the target contract transactions are being checked
        require(to == target, "only checking transactions to the Game contract");

        // load in the function selector
        bytes4 selector;
        assembly {
            // offset the data by 0x20 because the first 32 bytes just contains the length
            selector := mload(add(data, 0x20))
        }

        // function train(uint256 tokenId)
        if (selector == Game.train.selector) {
            uint256 tokenId;
            assembly {
                tokenId := mload(add(data, 0x24))
            }
            // perform bitmap check here for the token id and function selector 0
            require(
                _isFunctionSelectorAllowed(tokenId, 0),
                "train() not callable for this token Id"
            );
        }
        // function retire(uint256 tokenId)
        else if (selector == Game.retire.selector) {
            uint256 tokenId;
            assembly {
                tokenId := mload(add(data, 0x24))
            }
            // perform bitmap check here using token id and function selector 1
            require(
                _isFunctionSelectorAllowed(tokenId, 1),
                "retire() not callable for this token Id"
            );
        }
        // function changeTeam(Team newTeam)
        else if (selector == Game.changeTeam.selector) {
            // There is no token Id to check here, so changing teams is disabled by default,
            // but only if the safe has an active rental with a GameToken.
            require(
                activeRentals[safe] == 0,
                "changeTeam() not callable when holding a GameToken rental"
            );
        }
    }
}
"},"src/examples/revenue-share/ERC1155RewardHook.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {IERC165} from "@openzeppelin-contracts/utils/introspection/IERC165.sol";
import {IERC1155} from "@openzeppelin-contracts/token/ERC1155/IERC1155.sol";
import {
    IERC1155Receiver
} from "@openzeppelin-contracts/token/ERC1155/IERC1155Receiver.sol";

import {IHook} from "@src/interfaces/IHook.sol";
import {ISafe} from "@src/interfaces/ISafe.sol";

// Info stored about each rental
struct RentInfo {
    uint256 amount;
    uint256 lastRewardBlock;
}

// Info about the revenue share
struct RevenueShare {
    address lender;
}

contract ERC1155RewardHook is IHook, IERC1155Receiver {
    // privileged policy contracts
    address public createPolicy;
    address public stopPolicy;

    // tokens
    address public gameToken;
    IERC1155 public rewardToken;

    // the ID of the reward token
    uint256 public immutable rewardTokenId = 0;

    // award 1 gwei of reward token per block
    uint256 public immutable rewardPerBlock = 1e9;

    // hold info about an asset
    mapping(bytes32 assetHash => RentInfo rentInfo) public rentInfo;

    // hold info about accrued rewards
    mapping(address rewardedAddress => uint256 rewards) public accruedRewards;

    constructor(
        address _createPolicy,
        address _stopPolicy,
        address _gameToken,
        address _rewardToken
    ) {
        createPolicy = _createPolicy;
        stopPolicy = _stopPolicy;
        gameToken = _gameToken;
        rewardToken = IERC1155(_rewardToken);
    }

    modifier onlyCreatePolicy() {
        require(msg.sender == createPolicy, "not callable unless create policy");
        _;
    }

    modifier onlyStopPolicy() {
        require(msg.sender == stopPolicy, "not callable unless stop policy");
        _;
    }

    modifier onlySupportedTokens(address token) {
        require(token == gameToken, "token is not supported");
        _;
    }

    // This function will not be used in this hook, so it is unimplemented
    function onTransaction(
        address safe,
        address to,
        uint256 value,
        bytes memory data
    ) external view {}

    // hook handler for when a rental has started
    function onStart(
        address safe,
        address token,
        uint256 identifier,
        uint256 amount,
        bytes memory data
    ) external onlyCreatePolicy onlySupportedTokens(token) {
        // Decode the revenue share data
        RevenueShare memory revenueShare = abi.decode(data, (RevenueShare));

        // calculate the hash for this asset
        bytes32 assetHash = keccak256(abi.encode(safe, token, identifier));

        // get the last block that the rewards were accrued
        uint256 lastBlock = rentInfo[assetHash].lastRewardBlock;

        // get the amount currently stored
        uint256 currentAmount = rentInfo[assetHash].amount;

        // if the last block that a reward was accrued exists and the amount is nonzero,
        // calculate the latest reward. Otherwise, this is a first-time deposit so
        // there are no rewards earned.
        if (lastBlock > 0 && currentAmount > 0) {
            // place safe on stack to avoid stack too deep
            address _safe = safe;

            // The amount of blocks to reward
            uint256 blocksToReward = block.number - lastBlock;

            // since the last time reward were accrued, the reward is distributed per block per token stored.
            // Divide by 1e18 to account for token decimals
            uint256 latestAccruedRewards = (blocksToReward *
                rewardPerBlock *
                currentAmount) / 1e18;

            // determine the split of the rewards for the lender
            uint256 lenderAccruedRewards = latestAccruedRewards / 2;

            // determine the split of the rewards for the renter
            uint256 renterAccruedRewards = latestAccruedRewards - lenderAccruedRewards;

            // Effect: accrue rewards to the lender
            accruedRewards[revenueShare.lender] += lenderAccruedRewards;

            // Effect: accrue rewards to the safe/renter
            accruedRewards[_safe] += renterAccruedRewards;
        }

        // Effect: update the amount of tokens currently rented
        rentInfo[assetHash].amount += amount;

        // Effect: update the latest block that rewards were accrued
        rentInfo[assetHash].lastRewardBlock = block.number;
    }

    // handler for when a rental has stopped
    function onStop(
        address safe,
        address token,
        uint256 identifier,
        uint256 amount,
        bytes memory data
    ) external onlyStopPolicy onlySupportedTokens(token) {
        // Decode the revenue share data
        RevenueShare memory revenueShare = abi.decode(data, (RevenueShare));

        // calculate the hash for this asset
        bytes32 assetHash = keccak256(abi.encode(safe, token, identifier));

        // get the last block that the rewards were accrued
        uint256 lastBlock = rentInfo[assetHash].lastRewardBlock;

        // get the amount currently stored
        uint256 currentAmount = rentInfo[assetHash].amount;

        // on a stop, the last block since rewards were accrued and the amount should both be nonzero
        require(lastBlock > 0 && currentAmount > 0, "values should be nonzero");

        // place safe on stack to avoid stack too deep
        address _safe = safe;

        // The amount of blocks to reward
        uint256 blocksToReward = block.number - lastBlock;

        // since the last time reward were accrued, the reward is distributed per block per token stored.
        // Divide by 1e18 to account for token decimals
        uint256 latestAccruedRewards = (blocksToReward * rewardPerBlock * currentAmount) /
            1e18;

        // determine the split of the rewards for the lender
        uint256 lenderAccruedRewards = latestAccruedRewards / 2;

        // determine the split of the rewards for the renter
        uint256 renterAccruedRewards = latestAccruedRewards - lenderAccruedRewards;

        // Effect: accrue rewards to the lender
        accruedRewards[revenueShare.lender] += lenderAccruedRewards;

        // Effect: accrue rewards to the safe/renter
        accruedRewards[_safe] += renterAccruedRewards;

        // Effect: update the amount of tokens currently rented
        rentInfo[assetHash].amount -= amount;

        // Effect: update the latest block that rewards were accrued
        rentInfo[assetHash].lastRewardBlock = block.number;
    }

    function claimRewards(address rewardedAddress) external {
        // check if the caller is the lender or is a rental safe
        bool isClaimer = msg.sender == rewardedAddress;

        // make sure the caller is the claimer, or they are the owner
        // of the safe
        require(
            isClaimer || ISafe(rewardedAddress).isOwner(msg.sender),
            "not allowed to access rewards for this safe"
        );

        // store the amount to withdraw
        uint256 withdrawAmount = accruedRewards[rewardedAddress];

        // Effect: update the accrued rewards
        accruedRewards[rewardedAddress] = 0;

        // Interaction: Transfer the accrued rewards
        rewardToken.safeTransferFrom(
            address(this),
            msg.sender,
            rewardTokenId,
            withdrawAmount,
            bytes("")
        );
    }

    function onERC1155Received(
        address,
        address,
        uint256,
        uint256,
        bytes calldata
    ) external pure returns (bytes4) {
        return
            bytes4(keccak256("onERC1155Received(address,address,uint256,uint256,bytes)"));
    }

    function onERC1155BatchReceived(
        address,
        address,
        uint256[] calldata,
        uint256[] calldata,
        bytes calldata
    ) external pure returns (bytes4) {
        return
            bytes4(
                keccak256(
                    "onERC1155BatchReceived(address,address,uint256[],uint256[],bytes)"
                )
            );
    }

    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {
        return
            interfaceId == type(IERC165).interfaceId ||
            interfaceId == type(IERC1155).interfaceId;
    }
}
"},"src/examples/revenue-share/ERC20RewardHook.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin-contracts/token/ERC20/IERC20.sol";

import {IHook} from "@src/interfaces/IHook.sol";
import {ISafe} from "@src/interfaces/ISafe.sol";

// Info stored about each rental
struct RentInfo {
    uint256 amount;
    uint256 lastRewardBlock;
}

// Info about the revenue share
struct RevenueShare {
    address lender;
    uint256 lenderShare;
}

contract ERC20RewardHook is IHook {
    // privileged policy contracts
    address public createPolicy;
    address public stopPolicy;

    // ERC20 tokens
    address public gameToken;
    IERC20 public rewardToken;

    // award 1 gwei of reward token per block
    uint256 public immutable rewardPerBlock = 1e9;

    // hold info about an asset
    mapping(bytes32 assetHash => RentInfo rentInfo) public rentInfo;

    // hold info about accrued rewards
    mapping(address rewardedAddress => uint256 rewards) public accruedRewards;

    constructor(
        address _createPolicy,
        address _stopPolicy,
        address _gameToken,
        address _rewardToken
    ) {
        createPolicy = _createPolicy;
        stopPolicy = _stopPolicy;
        gameToken = _gameToken;
        rewardToken = IERC20(_rewardToken);
    }

    modifier onlyCreatePolicy() {
        require(msg.sender == createPolicy, "not callable unless create policy");
        _;
    }

    modifier onlyStopPolicy() {
        require(msg.sender == stopPolicy, "not callable unless stop policy");
        _;
    }

    modifier onlySupportedTokens(address token) {
        require(token == gameToken, "token is not supported");
        _;
    }

    // This function will not be used in this hook, so it is unimplemented
    function onTransaction(
        address safe,
        address to,
        uint256 value,
        bytes memory data
    ) external view {}

    // hook handler for when a rental has started
    function onStart(
        address safe,
        address token,
        uint256 identifier,
        uint256 amount,
        bytes memory data
    ) external onlyCreatePolicy onlySupportedTokens(token) {
        // Decode the revenue split data
        RevenueShare memory revenueShare = abi.decode(data, (RevenueShare));

        // require that the split adds to 100
        require(
            revenueShare.lenderShare <= 100,
            "split value must be less than or equal to 100"
        );

        // calculate the hash for this asset
        bytes32 assetHash = keccak256(abi.encode(safe, token, identifier));

        // get the last block that the rewards were accrued
        uint256 lastBlock = rentInfo[assetHash].lastRewardBlock;

        // get the amount currently stored
        uint256 currentAmount = rentInfo[assetHash].amount;

        // if the last block that a reward was accrued exists and the amount is nonzero,
        // calculate the latest reward. Otherwise, this is a first-time deposit so
        // there are no rewards earned.
        if (lastBlock > 0 && currentAmount > 0) {
            // place safe on stack to avoid stack too deep
            address _safe = safe;

            // The amount of blocks to reward
            uint256 blocksToReward = block.number - lastBlock;

            // since the last time reward were accrued, the reward is distributed per block per token stored.
            // Divide by 1e18 to account for token decimals
            uint256 latestAccruedRewards = (blocksToReward *
                rewardPerBlock *
                currentAmount) / 1e18;

            // determine the split of the rewards for the lender
            uint256 lenderAccruedRewards = (latestAccruedRewards *
                revenueShare.lenderShare) / 100;

            // determine the split of the rewards for the renter
            uint256 renterAccruedRewards = latestAccruedRewards - lenderAccruedRewards;

            // Effect: accrue rewards to the lender
            accruedRewards[revenueShare.lender] += lenderAccruedRewards;

            // Effect: accrue rewards to the safe/renter
            accruedRewards[_safe] += renterAccruedRewards;
        }

        // Effect: update the amount of tokens currently rented
        rentInfo[assetHash].amount += amount;

        // Effect: update the latest block that rewards were accrued
        rentInfo[assetHash].lastRewardBlock = block.number;
    }

    // handler for when a rental has stopped
    function onStop(
        address safe,
        address token,
        uint256 identifier,
        uint256 amount,
        bytes memory data
    ) external onlyStopPolicy onlySupportedTokens(token) {
        // Decode the revenue split data
        RevenueShare memory revenueShare = abi.decode(data, (RevenueShare));

        // require that the split adds to 100
        require(
            revenueShare.lenderShare <= 100,
            "split value must be less than or equal to 100"
        );

        // calculate the hash for this asset
        bytes32 assetHash = keccak256(abi.encode(safe, token, identifier));

        // get the last block that the rewards were accrued
        uint256 lastBlock = rentInfo[assetHash].lastRewardBlock;

        // get the amount currently stored
        uint256 currentAmount = rentInfo[assetHash].amount;

        // on a stop, the last block since rewards were accrued and the amount should both be nonzero
        require(lastBlock > 0 && currentAmount > 0, "values should be nonzero");

        // place safe on stack to avoid stack too deep
        address _safe = safe;

        // The amount of blocks to reward
        uint256 blocksToReward = block.number - lastBlock;

        // since the last time reward were accrued, the reward is distributed per block per token stored.
        // Divide by 1e18 to account for token decimals
        uint256 latestAccruedRewards = (blocksToReward * rewardPerBlock * currentAmount) /
            1e18;

        // determine the split of the rewards for the lender
        uint256 lenderAccruedRewards = (latestAccruedRewards * revenueShare.lenderShare) /
            100;

        // determine the split of the rewards for the renter
        uint256 renterAccruedRewards = latestAccruedRewards - lenderAccruedRewards;

        // Effect: accrue rewards to the lender
        accruedRewards[revenueShare.lender] += lenderAccruedRewards;

        // Effect: accrue rewards to the safe/renter
        accruedRewards[_safe] += renterAccruedRewards;

        // Effect: update the amount of tokens currently rented
        rentInfo[assetHash].amount -= amount;

        // Effect: update the latest block that rewards were accrued
        rentInfo[assetHash].lastRewardBlock = block.number;
    }

    function claimRewards(address rewardedAddress) external {
        // check if the caller is the lender or is a rental safe
        bool isClaimer = msg.sender == rewardedAddress;

        // make sure the caller is the claimer, or they are the owner
        // of the safe
        require(
            isClaimer || ISafe(rewardedAddress).isOwner(msg.sender),
            "not allowed to access rewards for this safe"
        );

        // store the amount to withdraw
        uint256 withdrawAmount = accruedRewards[rewardedAddress];

        // Effect: update the accrued rewards
        accruedRewards[rewardedAddress] = 0;

        // Interaction: Transfer the accrued rewards
        rewardToken.transfer(msg.sender, withdrawAmount);
    }
}
