pragma solidity ^0.8.0;

import {ReceivedItem, SpentItem} from "@seaport-types/lib/ConsiderationStructs.sol";

/////////////////////////////////////////////////////////////////////////////////
//                           Order Creation Structs                            //
/////////////////////////////////////////////////////////////////////////////////

/**
 * @dev Defines the supported order types in a rental. BASE orders require that rental
 *      assets are offered up in exchange for some ERC20 payment. PAY orders must contain
 *      only offer items where at least one is a rental asset and at least one is a
 *      payment. These orders are paired with PAYEE orders only contain consideration
 *      items where at least one is a rental asset and at least one is a payment.
 */
enum OrderType {
    // Offer items: all must be ERC721/ERC1155.
    // Consideration items: all must be ERC20.
    BASE,
    // Offer items: at least one ERC721/ERC1155, at least one ERC20.
    // Consideration items: none.
    PAY,
    // Offer items: none.
    // Consideration items: at least one ERC721/ERC1155, at least one ERC20.
    PAYEE
}

/**
 * @dev A hook contains three components: an address of the hook which will activate if a
 *      path is present to the hook, the index of the item associated with this hook in
 *      the order (it will always be an offer item), and any arbitrary data that the
 *      offerer deems important to pass along to the call with the hook on rental start.
 */
struct Hook {
    // The hook contract.
    address target;
    // Index of the item in the order to apply the hook to.
    uint256 itemIndex;
    // Any extra data that the hook will need.
    bytes extraData;
}

/**
 * @dev Order metadata contains all the details supplied by the offerer when they sign an
 *      order. These items include the type of rental order, how long the rental will be
 *      active, any hooks associated with the order, and any data that should be emitted
 *      when the rental starts.
 */
struct OrderMetadata {
    // Type of order being created.
    OrderType orderType;
    // Duration of the rental in seconds.
    uint256 rentDuration;
    // Hooks that will act as middleware for the items in the order.
    Hook[] hooks;
    // Any extra data to be emitted upon order fulfillment.
    bytes emittedExtraData;
}

/**
 * @dev Order fulfillment data contains details supplied by the fulfiller of the order.
 *      Currently, the only data needed is the expected rental wallet address which will
 *      receive the rented assets. This address is used to check against the fulfiller of
 *      the order to make sure they are the owner of the rental safe recipient address.
 */
struct OrderFulfillment {
    // Rental wallet address.
    address recipient;
}

/////////////////////////////////////////////////////////////////////////////////
//                             Rental Order Structs                            //
/////////////////////////////////////////////////////////////////////////////////

/**
 * @dev Defines the different types of assets that a rental order supports.
 */
enum ItemType {
    // ERC721 assets.
    ERC721,
    // ERC1155 assets.
    ERC1155,
    // ERC20 assets.
    ERC20
}

/**
 * @dev Defines which party will receive an asset after a rental is settled.
 */
enum SettleTo {
    // Lender of the rental order.
    LENDER,
    // Renter of the rental order.
    RENTER
}

/**
 * @dev Defines a rental ID which is a hash of unique markers on an asset. Namely, the
 *      recipient of the asset, the asset address, and the asset identifier.
 */
type RentalId is bytes32;

/**
 * @dev Used to transport rental asset update information. Contains data for a
 *      single rental asset: a rental ID and the amount of tokens rented.
 */
struct RentalAssetUpdate {
    RentalId rentalId;
    uint256 amount;
}

/**
 * @dev Defines an item which is part of a rental order. Contains item type, EOA to
 *      settle the asset to, address of the token, amount of the token rented, and
 *      identifier of the token.
 */
struct Item {
    ItemType itemType;
    SettleTo settleTo;
    address token;
    uint256 amount;
    uint256 identifier;
}

/**
 * @dev Defines a rental order. This order is contructed from a single seaport order when
 *      a rental is created. To stop a rental, this order will need to be provided back
 *      to the protocol. Since it is not stored in long form, an event is emitted when
 *      the rental is started to provide all the data necessary to reconstruct the rental
 *      order.
 */
struct RentalOrder {
    bytes32 seaportOrderHash;
    Item[] items;
    Hook[] hooks;
    OrderType orderType;
    address lender;
    address renter;
    address rentalWallet;
    uint256 startTimestamp;
    uint256 endTimestamp;
}

/////////////////////////////////////////////////////////////////////////////////
//                               Payload Structs                               //
/////////////////////////////////////////////////////////////////////////////////

/**
 * @dev Used as a vehicle for extra data that is needed for the rental, which is provided to
 *      the seaport order during fulfillment. The hash of the metadata is checked against
 *      the hash stored in the signed seaport order to make sure the data matches.
 */
struct RentPayload {
    OrderFulfillment fulfillment;
    OrderMetadata metadata;
    uint256 expiration;
    address intendedFulfiller;
}

/**
 * @dev Converts data received from the seaport zone contract into a single struct that
 *      is easier to work with during rental creation.
 */
struct SeaportPayload {
    bytes32 orderHash;
    bytes32 zoneHash;
    SpentItem[] offer;
    ReceivedItem[] consideration;
    ReceivedItem[] totalExecutions;
    address fulfiller;
    address offerer;
}

/////////////////////////////////////////////////////////////////////////////////
//                              Kernel Structs                                 //
/////////////////////////////////////////////////////////////////////////////////

/**
 * @dev Defines the actions which can be carried out by the executor of the kernel.
 */
enum Actions {
    // Installs a new module.
    InstallModule,
    // Changes the 5-character keycode from one module to point to a new module.
    UpgradeModule,
    // Grants a policy's access to module permissioned module functionality.
    ActivatePolicy,
    // Revokes a policy's access to permissioned module functionality.
    DeactivatePolicy,
    // Changes the address of the executor role.
    ChangeExecutor,
    // Changes the address of the admin role.
    ChangeAdmin,
    // Migrates the kernel to a new contract. This can only be done once per contract.
    MigrateKernel
}

/**
 * @dev Defines permission for a policy to have access to the `funcSelector` at a
 *      specific module contract via its keycode.
 */
struct Permissions {
    Keycode keycode;
    bytes4 funcSelector;
}

/**
 * @dev A 5-character keycode that references a module contract.
 */
type Keycode is bytes5;

/**
 * @dev A unique role which can be granted or revoked by the admin.
 */
type Role is bytes32;
"},"src/libraries/RentalUtils.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import {
    ReceivedItem,
    SpentItem,
    ItemType as SeaportItemType
} from "@seaport-types/lib/ConsiderationStructs.sol";

import {
    RentalOrder,
    RentalId,
    RentalAssetUpdate,
    Item,
    ItemType,
    OrderType
} from "@src/libraries/RentalStructs.sol";

/**
 * @title RentalUtils
 * @notice Contains logic for working with rental IDs and various assertion
 *         helper functions.
 */
library RentalUtils {
    /////////////////////////////////////////////////////////////////////////////////
    //                               Rental ID Utils                               //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @dev Generates a hashed `RentalId` type out of a recipient, token, and identifier.
     *
     * @param recipient  Address which will receive the rental asset.
     * @param token      Address of the rental asset.
     * @param identifier Identifier for the rental asset.
     *
     * @return id Rental ID generated from the input values.
     */
    function getItemPointer(
        address recipient,
        address token,
        uint256 identifier
    ) internal pure returns (RentalId id) {
        id = RentalId.wrap(keccak256(abi.encodePacked(recipient, token, identifier)));
    }

    /**
     * @dev Converts an `Item` and a recipient address into a `RentalId`.
     *
     * @param rentalItem The item to convert into a `RentalId`.
     * @param recipient  Address which will receive the rental asset.
     *
     * @return rentalId Rental ID generated from the input values.
     *
     */
    function toRentalId(
        Item memory rentalItem,
        address recipient
    ) internal pure returns (RentalId rentalId) {
        // Convert the rental item into a rental ID.
        return getItemPointer(recipient, rentalItem.token, rentalItem.identifier);
    }

    /**
     * @dev Converts an array of `Item` and a recipient address into an array of
     *      `RentalId`.
     *
     * @param rentalItems The items to convert into a `RentalId` array.
     * @param recipient   Address which will receive the rental asset.
     *
     * @return rentalIds Rental IDs generated from the input values.
     */
    function toRentalIds(
        Item[] memory rentalItems,
        address recipient
    ) internal pure returns (RentalId[] memory rentalIds) {
        rentalIds = new RentalId[](rentalItems.length);

        for (uint256 i; i < rentalIds.length; ++i) {
            // Convert the rental item into a rental ID.
            rentalIds[i] = getItemPointer(
                recipient,
                rentalItems[i].token,
                rentalItems[i].identifier
            );
        }
    }

    /**
     * @dev Converts an `Item` and a recipient address into a `RentalAssetUpdate`.
     *
     * @param item      The item to convert into a `RentalAssetupdate`.
     * @param recipient Address which will receive the rental asset.
     */
    function toRentalAssetUpdate(
        Item memory item,
        address recipient
    ) internal pure returns (RentalAssetUpdate memory rentalAssetupdate) {
        return RentalAssetUpdate(toRentalId(item, recipient), item.amount);
    }

    /////////////////////////////////////////////////////////////////////////////////
    //                               Item Assertions                               //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @dev Asserts whether an `Item` represents an ERC721 token.
     *
     * @return Whether the item is an ERC721 token.
     */
    function isERC721(Item memory item) internal pure returns (bool) {
        return item.itemType == ItemType.ERC721;
    }

    /**
     * @dev Asserts whether a `SpentItem` represents an ERC721 token.
     *
     * @return Whether the item is an ERC721 token.
     */
    function isERC721(SpentItem memory item) internal pure returns (bool) {
        return item.itemType == SeaportItemType.ERC721;
    }

    /**
     * @dev Asserts whether a `ReceivedItem` represents an ERC721 token.
     *
     * @return Whether the item is an ERC721 token.
     */
    function isERC721(ReceivedItem memory item) internal pure returns (bool) {
        return item.itemType == SeaportItemType.ERC721;
    }

    /**
     * @dev Asserts whether an `Item` represents an ERC1155 token.
     *
     * @return Whether the item is an ERC1155 token.
     */
    function isERC1155(Item memory item) internal pure returns (bool) {
        return item.itemType == ItemType.ERC1155;
    }

    /**
     * @dev Asserts whether a `SpentItem` represents an ERC1155 token.
     *
     * @return Whether the item is an ERC1155 token.
     */
    function isERC1155(SpentItem memory item) internal pure returns (bool) {
        return item.itemType == SeaportItemType.ERC1155;
    }

    /**
     * @dev Asserts whether a `ReceivedItem` represents an ERC1155 token.
     *
     * @return Whether the item is an ERC1155 token.
     */
    function isERC1155(ReceivedItem memory item) internal pure returns (bool) {
        return item.itemType == SeaportItemType.ERC1155;
    }

    /**
     * @dev Asserts whether an `Item` represents an ERC20 token.
     *
     * @return Whether the item is an ERC20 token.
     */
    function isERC20(Item memory item) internal pure returns (bool) {
        return item.itemType == ItemType.ERC20;
    }

    /**
     * @dev Asserts whether a `SpentItem` represents an ERC20 token.
     *
     * @return Whether the item is an ERC20 token.
     */
    function isERC20(SpentItem memory item) internal pure returns (bool) {
        return item.itemType == SeaportItemType.ERC20;
    }

    /**
     * @dev Asserts whether a `ReceivedItem` represents an ERC20 token.
     *
     * @return Whether the item is an ERC20 token.
     */
    function isERC20(ReceivedItem memory item) internal pure returns (bool) {
        return item.itemType == SeaportItemType.ERC20;
    }

    /**
     * @dev Asserts whether an `Item` represents a rented asset.
     *
     * @return Whether the item is a rented asset.
     */
    function isRental(Item memory item) internal pure returns (bool) {
        return isERC721(item) || isERC1155(item);
    }

    /**
     * @dev Asserts whether a `SpentItem` represents a rented asset.
     *
     * @return Whether the item is a rented asset.
     */
    function isRental(SpentItem memory item) internal pure returns (bool) {
        return isERC721(item) || isERC1155(item);
    }

    /**
     * @dev Asserts whether a `ReceivedItem` represents a rented asset.
     *
     * @return Whether the item is a rented asset.
     */
    function isRental(ReceivedItem memory item) internal pure returns (bool) {
        return isERC721(item) || isERC1155(item);
    }

    /////////////////////////////////////////////////////////////////////////////////
    //                              Order Assertions                               //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @dev Asserts whether the order is a Base order.
     *
     * @return Whether the order is a Base order.
     */
    function isBaseOrder(OrderType orderType) internal pure returns (bool) {
        return orderType == OrderType.BASE;
    }

    /**
     * @dev Asserts whether the order is a Pay order.
     *
     * @return Whether the order is a Pay order.
     */
    function isPayOrder(OrderType orderType) internal pure returns (bool) {
        return orderType == OrderType.PAY;
    }

    /**
     * @dev Asserts whether the order is a Payee order.
     *
     * @return Whether the order is a Payee order.
     */
    function isPayeeOrder(OrderType orderType) internal pure returns (bool) {
        return orderType == OrderType.PAYEE;
    }
}
"},"src/modules/PaymentEscrow.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin-contracts/token/ERC20/IERC20.sol";

import {Kernel, Module, Keycode} from "@src/Kernel.sol";
import {Proxiable} from "@src/proxy/Proxiable.sol";
import {
    RentalOrder,
    Item,
    ItemType,
    SettleTo,
    OrderType
} from "@src/libraries/RentalStructs.sol";
import {Errors} from "@src/libraries/Errors.sol";
import {Events} from "@src/libraries/Events.sol";
import {RentalUtils} from "@src/libraries/RentalUtils.sol";

/**
 * @title PaymentEscrowBase
 * @notice Storage exists in its own base contract to avoid storage slot mismatch during upgrades.
 */
contract PaymentEscrowBase {
    // Keeps a record of the current token balances in the escrow.
    mapping(address token => uint256 amount) public balanceOf;

    // Fee percentage taken from payments.
    uint256 public fee;
}

/**
 * @title PaymentEscrow
 * @notice Module dedicated to escrowing rental payments while rentals are active. When
 *         rentals are stopped, this module will determine payouts to all parties and a
 *         fee will be reserved to be withdrawn later by a protocol admin.
 */
contract PaymentEscrow is Proxiable, Module, PaymentEscrowBase {
    using RentalUtils for Item;
    using RentalUtils for OrderType;

    /////////////////////////////////////////////////////////////////////////////////
    //                         Kernel Module Configuration                         //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @dev Instantiate this contract as a module. When using a proxy, the kernel address
     *      should be set to address(0).
     *
     * @param kernel_ Address of the kernel contract.
     */
    constructor(Kernel kernel_) Module(kernel_) {}

    /**
     * @notice Instantiates this contract as a module via a proxy.
     *
     * @param kernel_ Address of the kernel contract.
     */
    function MODULE_PROXY_INSTANTIATION(
        Kernel kernel_
    ) external onlyByProxy onlyUninitialized {
        kernel = kernel_;
        initialized = true;
    }

    /**
     * @notice Specifies which version of a module is being implemented.
     */
    function VERSION() external pure override returns (uint8 major, uint8 minor) {
        return (1, 0);
    }

    /**
     * @notice Defines the keycode for this module.
     */
    function KEYCODE() public pure override returns (Keycode) {
        return Keycode.wrap("ESCRW");
    }

    /////////////////////////////////////////////////////////////////////////////////
    //                            Internal Functions                               //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @dev Calculates the fee based on the fee numerator set by an admin.
     *
     * @param amount Amount for which to calculate the fee.
     */
    function _calculateFee(uint256 amount) internal view returns (uint256) {
        // Uses 10,000 as a denominator for the fee.
        return (amount * fee) / 10000;
    }

    /**
     * @dev Safe transfer for ERC20 tokens that do not consistently renturn true/false.
     *
     * @param token Asset address which is being sent.
     * @param to    Destination address for the transfer.
     * @param value Amount of the asset being transferred.
     */
    function _safeTransfer(address token, address to, uint256 value) internal {
        // Call transfer() on the token.
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, value)
        );

        // Because both reverting and returning false are allowed by the ERC20 standard
        // to indicate a failed transfer, we must handle both cases.
        //
        // If success is false, the ERC20 contract reverted.
        //
        // If success is true, we must check if return data was provided. If no return
        // data is provided, then no revert occurred. But, if return data is provided,
        // then it must be decoded into a bool which will indicate the success of the
        // transfer.
        if (!success || (data.length != 0 && !abi.decode(data, (bool)))) {
            revert Errors.PaymentEscrowModule_PaymentTransferFailed(token, to, value);
        }
    }

    /**
     * @dev Calculates the pro-rata split based on the amount of time that has elapsed in
     *      a rental order. If there are not enough funds to split perfectly, rounding is
     *      done to make the split as fair as possible.
     *
     * @param amount      Amount of tokens for which to calculate the split.
     * @param elapsedTime Elapsed time since the rental started.
     * @param totalTime   Total time window of the rental from start to end.
     *
     * @return renterAmount Payment amount to send to the renter.
     * @return lenderAmount Payment amoutn to send to the lender.
     */
    function _calculatePaymentProRata(
        uint256 amount,
        uint256 elapsedTime,
        uint256 totalTime
    ) internal pure returns (uint256 renterAmount, uint256 lenderAmount) {
        // Calculate the numerator and adjust by a multiple of 1000.
        uint256 numerator = (amount * elapsedTime) * 1000;

        // Calculate the result, but bump by 500 to add a rounding adjustment. Then,
        // reduce by a multiple of 1000.
        renterAmount = ((numerator / totalTime) + 500) / 1000;

        // Calculate lender amount from renter amount so no tokens are left behind.
        lenderAmount = amount - renterAmount;
    }

    /**
     * @dev Settles a payment via a pro-rata split. After payments are calculated, they
     *      are transferred to their respective recipients.
     *
     * @param token       Token address for which to settle a payment.
     * @param amount      Amount of the token to settle.
     * @param lender      Lender account.
     * @param renter      Renter accoutn.
     * @param elapsedTime Elapsed time since the rental started.
     * @param totalTime   Total time window of the rental from start to end.
     */
    function _settlePaymentProRata(
        address token,
        uint256 amount,
        address lender,
        address renter,
        uint256 elapsedTime,
        uint256 totalTime
    ) internal {
        // Calculate the pro-rata payment for renter and lender.
        (uint256 renterAmount, uint256 lenderAmount) = _calculatePaymentProRata(
            amount,
            elapsedTime,
            totalTime
        );

        // Send the lender portion of the payment.
        _safeTransfer(token, lender, lenderAmount);

        // Send the renter portion of the payment.
        _safeTransfer(token, renter, renterAmount);
    }

    /**
     * @dev Settles a payment by sending the full amount to one address.
     *
     * @param token    Token address for which to settle a payment.
     * @param amount   Amount of the token to settle.
     * @param settleTo Specifies whether to settle to the lender or the renter.
     * @param lender   Lender account.
     * @param renter   Renter account.
     */
    function _settlePaymentInFull(
        address token,
        uint256 amount,
        SettleTo settleTo,
        address lender,
        address renter
    ) internal {
        // Determine the address that this payment will settle to.
        address settleToAddress = settleTo == SettleTo.LENDER ? lender : renter;

        // Send the payment.
        _safeTransfer(token, settleToAddress, amount);
    }

    /**
     * @dev Settles alls payments contained in the given item. Uses a pro-rata or in full
     *      scheme depending on the order type and when the order was stopped.
     *
     * @param items     Items present in the order.
     * @param orderType Type of the order.
     * @param lender    Lender account.
     * @param renter    Renter account.
     * @param start     Timestamp that the rental began.
     * @param end       Timestamp that the rental expires at.
     */
    function _settlePayment(
        Item[] calldata items,
        OrderType orderType,
        address lender,
        address renter,
        uint256 start,
        uint256 end
    ) internal {
        // Calculate the time values.
        uint256 elapsedTime = block.timestamp - start;
        uint256 totalTime = end - start;

        // Determine whether the rental order has ended.
        bool isRentalOver = elapsedTime >= totalTime;

        // Loop through each item in the order.
        for (uint256 i = 0; i < items.length; ++i) {
            // Get the item.
            Item memory item = items[i];

            // Check that the item is a payment.
            if (item.isERC20()) {
                // Set a placeholder payment amount which can be reduced in the
                // presence of a fee.
                uint256 paymentAmount = item.amount;

                // Take a fee on the payment amount if the fee is on.
                if (fee != 0) {
                    // Calculate the new fee.
                    uint256 paymentFee = _calculateFee(paymentAmount);

                    // Adjust the payment amount by the fee.
                    paymentAmount -= paymentFee;
                }

                // Effect: Decrease the token balance. Use the payment amount pre-fee
                // so that fees can be taken.
                _decreaseDeposit(item.token, item.amount);

                // If its a PAY order but the rental hasn't ended yet.
                if (orderType.isPayOrder() && !isRentalOver) {
                    // Interaction: a PAY order which hasnt ended yet. Payout is pro-rata.
                    _settlePaymentProRata(
                        item.token,
                        paymentAmount,
                        lender,
                        renter,
                        elapsedTime,
                        totalTime
                    );
                }
                // If its a PAY order and the rental is over, or, if its a BASE order.
                else if (
                    (orderType.isPayOrder() && isRentalOver) || orderType.isBaseOrder()
                ) {
                    // Interaction: a pay order or base order which has ended. Payout is in full.
                    _settlePaymentInFull(
                        item.token,
                        paymentAmount,
                        item.settleTo,
                        lender,
                        renter
                    );
                } else {
                    revert Errors.Shared_OrderTypeNotSupported(uint8(orderType));
                }
            }
        }
    }

    /**
     * @dev Decreases the tracked token balance of a particular token on the payment
     *      escrow contract.
     *
     * @param token  Token address.
     * @param amount Amount to decrease the balance by.
     */
    function _decreaseDeposit(address token, uint256 amount) internal {
        // Directly decrease the synced balance.
        balanceOf[token] -= amount;
    }

    /**
     * @dev Increases the tracked token balance of a particular token on the payment
     *      escrow contract.
     *
     * @param token  Token address.
     * @param amount Amount to increase the balance by.
     */
    function _increaseDeposit(address token, uint256 amount) internal {
        // Directly increase the synced balance.
        balanceOf[token] += amount;
    }

    /////////////////////////////////////////////////////////////////////////////////
    //                            External Functions                               //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @notice Settles the payment for a rental order by transferring all items marked as
     *         payments to their destination accounts. During the settlement process, if
     *         active, a fee is taken on the payment.
     *
     * @param order Rental order for which to settle a payment.
     */
    function settlePayment(RentalOrder calldata order) external onlyByProxy permissioned {
        // Settle all payments for the order.
        _settlePayment(
            order.items,
            order.orderType,
            order.lender,
            order.renter,
            order.startTimestamp,
            order.endTimestamp
        );
    }

    /**
     * @notice Settles the payments for multiple orders by looping through each one.
     *
     * @param orders Rental ordesr for which to settle payments.
     */
    function settlePaymentBatch(
        RentalOrder[] calldata orders
    ) external onlyByProxy permissioned {
        // Loop through each order.
        for (uint256 i = 0; i < orders.length; ++i) {
            // Settle all payments for the order.
            _settlePayment(
                orders[i].items,
                orders[i].orderType,
                orders[i].lender,
                orders[i].renter,
                orders[i].startTimestamp,
                orders[i].endTimestamp
            );
        }
    }

    /**
     * @notice When fungible tokens are transferred to the payment escrow contract,
     *         their balances should be increased.
     *
     * @param token  Token address for the asset.
     * @param amount Amount of the token transferred to the escrow
     */
    function increaseDeposit(
        address token,
        uint256 amount
    ) external onlyByProxy permissioned {
        // Cannot accept a payment of zero.
        if (amount == 0) {
            revert Errors.PaymentEscrow_ZeroPayment();
        }

        // Increase the deposit
        _increaseDeposit(token, amount);
    }

    /**
     * @notice Sets the numerator for the fee. The denominator will always be set at
     *         10,000.
     *
     * @param feeNumerator Numerator of the fee.
     */
    function setFee(uint256 feeNumerator) external onlyByProxy permissioned {
        // Cannot accept a fee numerator greater than 10000.
        if (feeNumerator > 10000) {
            revert Errors.PaymentEscrow_InvalidFeeNumerator();
        }

        // Set the fee.
        fee = feeNumerator;
    }

    /**
     * @notice Used to collect protocol fees. In addition, if funds are accidentally sent
     *         to the payment escrow contract, this function can be used to skim them off.
     *
     * @param token Address of the token to skim.
     * @param to    Address to send the collected tokens.
     */
    function skim(address token, address to) external onlyByProxy permissioned {
        // Fetch the currently synced balance of the escrow.
        uint256 syncedBalance = balanceOf[token];

        // Fetch the true token balance of the escrow.
        uint256 trueBalance = IERC20(token).balanceOf(address(this));

        // Calculate the amount to skim.
        uint256 skimmedBalance = trueBalance - syncedBalance;

        // Send the difference to the specified address.
        _safeTransfer(token, to, skimmedBalance);

        // Emit event with fees taken.
        emit Events.FeeTaken(token, skimmedBalance);
    }

    /**
     * @notice Upgrades the contract to a different implementation. This implementation
     *         contract must be compatible with ERC-1822 or else the upgrade will fail.
     *
     * @param newImplementation Address of the implementation contract to upgrade to.
     */
    function upgrade(address newImplementation) external onlyByProxy permissioned {
        // _upgrade is implemented in the Proxiable contract.
        _upgrade(newImplementation);
    }

    /**
     * @notice Freezes the contract which prevents upgrading the implementation contract.
     *         There is no way to unfreeze once a contract has been frozen.
     */
    function freeze() external onlyByProxy permissioned {
        // _freeze is implemented in the Proxiable contract.
        _freeze();
    }
}
"},"src/modules/Storage.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {Kernel, Module, Keycode} from "@src/Kernel.sol";
import {Proxiable} from "@src/proxy/Proxiable.sol";
import {RentalUtils} from "@src/libraries/RentalUtils.sol";
import {RentalId, RentalAssetUpdate} from "@src/libraries/RentalStructs.sol";
import {Errors} from "@src/libraries/Errors.sol";

/**
 * @title StorageBase
 * @notice Storage exists in its own base contract to avoid storage slot mismatch during upgrades.
 */
contract StorageBase {
    /////////////////////////////////////////////////////////////////////////////////
    //                                Rental Storage                               //
    /////////////////////////////////////////////////////////////////////////////////

    // Points an order hash to whether it is active.
    mapping(bytes32 orderHash => bool isActive) public orders;

    // Points an item ID to its number of actively rented tokens. This is used to
    // determine if an item is actively rented within the protocol. For ERC721, this
    // value will always be 1 when actively rented. Any inactive rentals will have a
    // value of 0.
    mapping(RentalId itemId => uint256 amount) public rentedAssets;

    /////////////////////////////////////////////////////////////////////////////////
    //                            Deployed Safe Storage                            //
    /////////////////////////////////////////////////////////////////////////////////

    // Records all safes that have been deployed by the protocol.
    mapping(address safe => uint256 nonce) public deployedSafes;

    // Records the total amount of deployed safes.
    uint256 public totalSafes;

    /////////////////////////////////////////////////////////////////////////////////
    //                                 Hook Storage                                //
    /////////////////////////////////////////////////////////////////////////////////

    // When interacting with the guard, any contracts that have hooks enabled
    // should have the guard logic routed through them.
    mapping(address to => address hook) internal _contractToHook;

    // Mapping of a bitmap which denotes the hook functions that are enabled.
    mapping(address hook => uint8 enabled) public hookStatus;

    /////////////////////////////////////////////////////////////////////////////////
    //                            Whitelist Storage                                //
    /////////////////////////////////////////////////////////////////////////////////

    // Allows the safe to delegate call to an approved address. For example, delegate
    // call to a contract that would swap out an old gnosis safe module for a new one.
    mapping(address delegate => bool isWhitelisted) public whitelistedDelegates;

    // Allows for the safe registration of extensions that can be enabled on a safe.
    mapping(address extension => bool isWhitelisted) public whitelistedExtensions;
}

/**
 * @title Storage
 * @notice Module dedicated to maintaining all the storage for the protocol. Includes
 *         storage for active rentals, deployed rental safes, hooks, and whitelists.
 */
contract Storage is Proxiable, Module, StorageBase {
    using RentalUtils for address;

    /////////////////////////////////////////////////////////////////////////////////
    //                         Kernel Module Configuration                         //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @dev Instantiate this contract as a module. When using a proxy, the kernel address
     *      should be set to address(0).
     *
     * @param kernel_ Address of the kernel contract.
     */
    constructor(Kernel kernel_) Module(kernel_) {}

    /**
     * @notice Instantiates this contract as a module via a proxy.
     *
     * @param kernel_ Address of the kernel contract.
     */
    function MODULE_PROXY_INSTANTIATION(
        Kernel kernel_
    ) external onlyByProxy onlyUninitialized {
        kernel = kernel_;
        initialized = true;
    }

    /**
     * @notice Specifies which version of a module is being implemented.
     */
    function VERSION() external pure override returns (uint8 major, uint8 minor) {
        return (1, 0);
    }

    /**
     * @notice Defines the keycode for this module.
     */
    function KEYCODE() public pure override returns (Keycode) {
        return Keycode.wrap("STORE");
    }

    /////////////////////////////////////////////////////////////////////////////////
    //                              View Functions                                 //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @notice Determines if an asset is actively being rented by a wallet.
     *
     * @param recipient  Address of the wallet which rents the asset.
     * @param token      Address of the token.
     * @param identifier ID of the token.
     */
    function isRentedOut(
        address recipient,
        address token,
        uint256 identifier
    ) external view returns (bool) {
        // calculate the rental ID
        RentalId rentalId = RentalUtils.getItemPointer(recipient, token, identifier);

        // Determine if there is a positive amount
        return rentedAssets[rentalId] != 0;
    }

    /**
     * @notice Fetches the hook address that is pointing at the the target.
     *
     * @param to Address which has a hook pointing to it.
     */
    function contractToHook(address to) external view returns (address) {
        // Fetch the hook that the address currently points to.
        address hook = _contractToHook[to];

        // This hook may have been disabled without setting a new hook to take its place.
        // So if the hook is disabled, then return the 0 address.
        return hookStatus[hook] != 0 ? hook : address(0);
    }

    /**
     * @notice Determines whether the `onTransaction()` function is enabled for the hook.
     *
     * @param hook Address of the hook contract.
     */
    function hookOnTransaction(address hook) external view returns (bool) {
        // 1 is 0x00000001. Determines if the masked bit is enabled.
        return (uint8(1) & hookStatus[hook]) != 0;
    }

    /**
     * @notice Determines whether the `onStart()` function is enabled for the hook.
     *
     * @param hook Address of the hook contract.
     */
    function hookOnStart(address hook) external view returns (bool) {
        // 2 is 0x00000010. Determines if the masked bit is enabled.
        return uint8(2) & hookStatus[hook] != 0;
    }

    /**
     * @notice Determines whether the `onStop()` function is enabled for the hook.
     *
     * @param hook Address of the hook contract.
     */
    function hookOnStop(address hook) external view returns (bool) {
        // 4 is 0x00000100. Determines if the masked bit is enabled.
        return uint8(4) & hookStatus[hook] != 0;
    }

    /////////////////////////////////////////////////////////////////////////////////
    //                            External Functions                               //
    /////////////////////////////////////////////////////////////////////////////////

    /**
     * @notice Adds an order hash to storage. Once an order hash is added to storage,
     *         the assets contained within are considered actively rented. Additionally,
     *         rental asset IDs are added to storage which creates a blocklist on those
     *         assets. When the blocklist is active, the protocol guard becomes active on
     *         them and prevents transfer or approval of the assets by the owner of the
     *         safe.
     *
     * @param orderHash          Hash of the rental order which is added to storage.
     * @param rentalAssetUpdates Asset update structs which are added to storage.
     */
    function addRentals(
        bytes32 orderHash,
        RentalAssetUpdate[] memory rentalAssetUpdates
    ) external onlyByProxy permissioned {
        // Add the order to storage.
        orders[orderHash] = true;

        // Add the rented items to storage.
        for (uint256 i = 0; i < rentalAssetUpdates.length; ++i) {
            RentalAssetUpdate memory asset = rentalAssetUpdates[i];

            // Update the order hash for that item.
            rentedAssets[asset.rentalId] += asset.amount;
        }
    }

    /**
     * @notice Removes an order hash from storage. Once an order hash is removed from
     *         storage, it can no longer be stopped since the protocol will have no
     *         record of the order. Addtionally, rental asset IDs are removed from
     *         storage. Once these hashes are removed, they are no longer blocklisted
     *         from being transferred out of the rental wallet by the owner.
     *
     * @param orderHash          Hash of the rental order which will be removed from
     *                           storage.
     * @param rentalAssetUpdates Asset update structs which will be removed from storage.
     */
    function removeRentals(
        bytes32 orderHash,
        RentalAssetUpdate[] calldata rentalAssetUpdates
    ) external onlyByProxy permissioned {
        // The order must exist to be deleted.
        if (!orders[orderHash]) {
            revert Errors.StorageModule_OrderDoesNotExist(orderHash);
        } else {
            // Delete the order from storage.
            delete orders[orderHash];
        }

        // Process each rental asset.
        for (uint256 i = 0; i < rentalAssetUpdates.length; ++i) {
            RentalAssetUpdate memory asset = rentalAssetUpdates[i];

            // Reduce the amount of tokens for the particular rental ID.
            rentedAssets[asset.rentalId] -= asset.amount;
        }
    }

    /**
     * @notice Behaves the same as `removeRentals()`, except that orders are processed in
     *          a loop.
     *
     * @param orderHashes        All order hashes which will be removed from storage.
     * @param rentalAssetUpdates Asset update structs which will be removed from storage.
     */
    function removeRentalsBatch(
        bytes32[] calldata orderHashes,
        RentalAssetUpdate[] calldata rentalAssetUpdates
    ) external onlyByProxy permissioned {
        // Delete the orders from storage.
        for (uint256 i = 0; i < orderHashes.length; ++i) {
            // The order must exist to be deleted.
            if (!orders[orderHashes[i]]) {
                revert Errors.StorageModule_OrderDoesNotExist(orderHashes[i]);
            } else {
                // Delete the order from storage.
                delete orders[orderHashes[i]];
            }
        }

        // Process each rental asset.
        for (uint256 i = 0; i < rentalAssetUpdates.length; ++i) {
            RentalAssetUpdate memory asset = rentalAssetUpdates[i];

            // Reduce the amount of tokens for the particular rental ID.
            rentedAssets[asset.rentalId] -= asset.amount;
        }
    }

    /**
     * @notice Adds the addresss of a rental safe to storage so that protocol-deployed
     *         rental safes can be distinguished from those deployed elsewhere.
     *
     * @param safe Address of the rental safe to add to storage.
     */
    function addRentalSafe(address safe) external onlyByProxy permissioned {
        // Get the new safe count.
        uint256 newSafeCount = totalSafes + 1;

        // Register the safe as deployed.
        deployedSafes[safe] = newSafeCount;

        // Increment nonce.
        totalSafes = newSafeCount;
    }

    /**
     * @notice Connects a hook to a destination address. Once an active path is made,
     *         any transactions originating from a rental safe to the target address
     *         will use a hook as middleware. The hook chosen is determined by the path
     *         set.
     *
     * @param to   Target address which will use a hook as middleware.
     * @param hook Address of the hook which will act as a middleware.
     */
    function updateHookPath(address to, address hook) external onlyByProxy permissioned {
        // Require that the `to` address is a contract.
        if (to.code.length == 0) revert Errors.StorageModule_NotContract(to);

        // Require that the `hook` address is a contract.
        if (hook.code.length == 0) revert Errors.StorageModule_NotContract(hook);

        // Point the `to` address to the `hook` address.
        _contractToHook[to] = hook;
    }

    /**
     * @notice Updates a hook with a bitmap that indicates its active functionality.
     *         A valid bitmap is any decimal value that is less than or equal
     *         to 7 (0x111).
     *
     * @param hook   Address of the hook contract.
     * @param bitmap Decimal value that defines the active functionality on the hook.
     */
    function updateHookStatus(
        address hook,
        uint8 bitmap
    ) external onlyByProxy permissioned {
        // Require that the `hook` address is a contract.
        if (hook.code.length == 0) revert Errors.StorageModule_NotContract(hook);

        // 7 is 0x00000111. This ensures that only a valid bitmap can be set.
        if (bitmap > uint8(7))
            revert Errors.StorageModule_InvalidHookStatusBitmap(bitmap);

        // Update the status of the hook.
        hookStatus[hook] = bitmap;
    }

    /**
     * @notice Toggles whether an address can be delegate called.
     *
     * @param delegate  Address which can be delegate called.
     * @param isEnabled Boolean indicating whether the address is enabled.
     */
    function toggleWhitelistDelegate(
        address delegate,
        bool isEnabled
    ) external onlyByProxy permissioned {
        whitelistedDelegates[delegate] = isEnabled;
    }

    /**
     * @notice Toggles whether an extension is whitelisted.
     *
     * @param extension Gnosis safe module which can be added to a rental safe.
     * @param isEnabled Boolean indicatingwhether the module is enabled.
     */
    function toggleWhitelistExtension(
        address extension,
        bool isEnabled
    ) external onlyByProxy permissioned {
        whitelistedExtensions[extension] = isEnabled;
    }

    /**
     * @notice Upgrades the contract to a different implementation. This implementation
     *         contract must be compatible with ERC-1822 or else the upgrade will fail.
     *
     * @param newImplementation Address of the implementation contract to upgrade to.
     */
    function upgrade(address newImplementation) external onlyByProxy permissioned {
        // _upgrade is implemented in the Proxiable contract.
        _upgrade(newImplementation);
    }

    /**
     * @notice Freezes the contract which prevents upgrading the implementation contract.
     *         There is no way to unfreeze once a contract has been frozen.
     */
    function freeze() external onlyByProxy permissioned {
        // _freeze is implemented in the Proxiable contract.
        _freeze();
    }
}
